def traffic_light_probability(Tg, Ty, Tr, n, observations, tq, cq):
    T = observations[1][0] - observations[0][0]
    while True:
        valid = True
        for i in range(1, n):
            expected_time = observations[i-1][0] + T * ((observations[i-1][0] // T) % 3)
            if (expected_time <= observations[i][0] < expected_time + Tg and observations[i][1] != 'green') or \
               (expected_time + Tg <= observations[i][0] < expected_time + Tg + Ty and observations[i][1] != 'yellow') or \
               (expected_time + Tg + Ty <= observations[i][0] < expected_time + Tg + Ty + Tr and observations[i][1] != 'red'):
                valid = False
                break
        if valid:
            break
        else:
            T += 1

    total_time = Tg + Ty + Tr
    if cq == 'green':
        return max(0, min((tq - observations[-1][0]) % total_time / Tg, 1))
    elif cq == 'yellow':
        return max(0, min(((tq - observations[-1][0]) % total_time - Tg) / Ty, 1))
    elif cq == 'red':
        return max(0, min(((tq - observations[-1][0]) % total_time - Tg - Ty) / Tr, 1))

