from fractions import Fraction

def traffic_light_probability(T_g, T_y, T_r, n, observations, query_time, query_color):
    total_cycle = T_g + T_y + T_r
    current_cycle_start = None

    def get_cycle_status(time):
        nonlocal current_cycle_start
        if current_cycle_start is None:
            current_cycle_start = time
        cycle_offset = (time - current_cycle_start) % total_cycle
        if cycle_offset < T_g:
            return "green"
        elif cycle_offset < T_g + T_y:
            return "yellow"
        else:
            return "red"

    observed_green = False
    observed_yellow = False
    observed_red = False

    for time, color in observations:
        current_color = get_cycle_status(time)
        if current_color != color:
            raise ValueError("Observation does not match the cycle")

        if color == "green":
            observed_green = True
        elif color == "yellow":
            observed_yellow = True
        elif color == "red":
            observed_red = True

    if not (observed_green and observed_yellow and observed_red):
        raise ValueError("Not all colors were observed")

    if query_color == "green":
        return Fraction(query_time - current_cycle_start, total_cycle).limit_denominator()
    elif query_color == "yellow":
        return Fraction((query_time - current_cycle_start + T_g) % total_cycle, total_cycle).limit_denominator()
    elif query_color == "red":
        return Fraction((query_time - current_cycle_start + T_g + T_y) % total_cycle, total_cycle).limit_denominator()
    else:
        raise ValueError("Invalid query color")

