def calculate_probability(Tg, Ty, Tr, n, observations, tq, cq):
    cycle_length = Tg + Ty + Tr
    current_color = None
    for t, c in observations:
        if current_color is None:
            current_color = c
        elif current_color != c:
            start_time = t - ((t - observations[0][0]) % cycle_length)
            break

    def get_color_at_time(t):
        local_t = t - start_time
        position_in_cycle = local_t % cycle_length
        if position_in_cycle < Tg:
            return 'green'
        elif position_in_cycle < Tg + Ty:
            return 'yellow'
        else:
            return 'red'

    return { 'green': 0, 'yellow': 0, 'red': 0 }[cq] / cycle_length

