import sys
from typing import List, Tuple

def get_cycle_time(Tg: int, Ty: int, Tr: int) -> int:
    return Tg + Ty + Tr

def get_light_state(time: int, start_time: int, Tg: int, Ty: int, Tr: int) -> str:
    cycle_length = get_cycle_time(Tg, Ty, Tr)
    relative_time = (time - start_time) % cycle_length
    if relative_time < Tg:
        return 'green'
    elif relative_time < Tg + Ty:
        return 'yellow'
    else:
        return 'red'

def estimate_start_time(Tg: int, Ty: int, Tr: int, observations: List[Tuple[int, str]]) -> float:
    cycle_length = get_cycle_time(Tg, Ty, Tr)
    total_count = len(observations)
    count_per_color = {'green': 0, 'yellow': 0, 'red': 0}

    for time, color in observations:
        relative_time = (time - observations[0][0]) % cycle_length
        if relative_time < Tg:
            count_per_color['green'] += 1
        elif relative_time < Tg + Ty:
            count_per_color['yellow'] += 1
        else:
            count_per_color['red'] += 1

    max_count = max(count_per_color.values())
    min_count = min(count_per_color.values())

    if max_count == total_count // 3 and min_count == total_count // 3:
        return observations[0][0]

    estimated_start = None
    for i in range(total_count):
        time, _ = observations[i]
        current_cycle = [(time - observations[0][0] + j * cycle_length) % cycle_length for j in range(3)]
        if all(cycle % Tg == 0 or cycle % (Tg + Ty) > Tg for cycle in current_cycle):
            estimated_start = time - Tg
            break

    if estimated_start is None:
        raise ValueError("Could not estimate start time")

    return estimated_start

def calculate_probability(start_time: int, Tg: int, Ty: int, Tr: int, query_time: int, query_color: str) -> float:
    cycle_length = get_cycle_time(Tg, Ty, Tr)
    relative_query_time = (query_time - start_time) % cycle_length
    if query_color == 'green':
        if relative_query_time < Tg:
            return 1.0
        else:
            return 0.0
    elif query_color == 'yellow':
        if relative_query_time >= Tg and relative_query_time < Tg + Ty:
            return 1.0
        else:
            return 0.0
    elif query_color == 'red':
        if relative_query_time >= Tg + Ty and relative_query_time < cycle_length:
            return 1.0
        else:
            return 0.0

